<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>东宫状态系统</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <link href="https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
    <style>
        @import url('https://fonts.googleapis.com/css2?family=ZCOOL+XiaoWei&display=swap');
        :root {
            --bg-color: rgba(250, 249, 245, 0.95);
            --border-color-main: #8D7B68;
            --border-color-light: #C8B6A6;
            --text-color: #3D352E;
            --accent-color: #A4907C;
            --button-hover-bg: #8D7B68;
            --font-main: 'Ma Shan Zheng', '楷体', 'KaiTi', 'STKaiti', serif;
            --shadow: 0 6px 20px rgba(61, 53, 46, 0.12);
            --transition: all 0.3s ease;
            --lust-color: #B53431;
            --lust-bar-bg: rgba(181, 52, 49, 0.2);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            background: linear-gradient(135deg, #f5f0e9 0%, #e8e1d7 100%);
            color: var(--text-color);
            min-height: 50vh;
            padding: 15px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        .container {
            width: 100%;
            max-width: 1200px;
            display: grid;
            grid-template-columns: 1fr;
            gap: 20px;
            margin: 15px auto;
        }

        @media (min-width: 992px) {
            .container {
                grid-template-columns: 1fr 320px;
            }
        }

        .status-container {
            background-color: var(--bg-color);
            border: 2px solid var(--border-color-main);
            border-radius: 12px;
            padding: 20px;
            box-shadow: var(--shadow);
            backdrop-filter: blur(3px);
            transition: var(--transition);
            max-height: 85vh;
            overflow-y: auto;
        }

        .header-info {
            text-align: center;
            font-size: clamp(1.1rem, 2vw, 1.3rem);
            color: var(--text-color);
            margin-bottom: 20px;
            padding-bottom: 12px;
            border-bottom: 1px solid var(--border-color-light);
            letter-spacing: 1px;
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 10px 15px;
        }

        .char-info, .location-info, .identity-info {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
            gap: 15px 20px;
            margin-bottom: 15px;
            font-size: clamp(1rem, 1.8vw, 1.1rem);
        }

        .identity-info {
            background-color: rgba(141, 123, 104, 0.08);
            padding: 10px 15px;
            border-radius: 8px;
            font-size: clamp(0.95rem, 1.6vw, 1rem);
        }

        .location-info {
            background-color: rgba(141, 123, 104, 0.08);
            padding: 10px;
            border-radius: 8px;
            font-size: clamp(1rem, 1.8vw, 1.1rem);
            justify-content: center;
        }

        .status-bar-container {
            margin: 20px 0;
            background: rgba(245, 239, 230, 0.5);
            padding: 12px;
            border-radius: 8px;
        }

        .status-bar-title {
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
            font-size: clamp(0.95rem, 1.5vw, 1.05rem);
            margin-bottom: 10px;
            font-weight: bold;
        }

        .progress-bar {
            width: 100%;
            height: 28px;
            background: #f0e6d2; /* 书本黄色背景 */
            border-radius: 14px;
            box-shadow: 
                inset 0 3px 8px rgba(0, 0, 0, 0.3),
                0 4px 10px rgba(0, 0, 0, 0.2);
            overflow: hidden;
            border: 2px solid #5d4a2a;
            position: relative;
        }

        .progress-bar-fill {
            height: 100%;
            border-radius: 14px;
            transition: width 0.8s cubic-bezier(0.22, 0.61, 0.36, 1);
            position: relative;
            overflow: hidden;
            width: 0;
        }

        .debuff-bar-fill {
            background: linear-gradient(90deg, 
                #ff6b6b 0%, 
                #ff0000 50%, 
                #8b0000 100%);
            box-shadow: 
                inset 0 0 15px rgba(255, 0, 0, 0.5),
                0 0 20px rgba(255, 0, 0, 0.4);
        }

        .lust-bar-fill {
            background: linear-gradient(90deg, 
                #ffb6c1 0%, 
                #ff69b4 50%, 
                #ff1493 100%);
            box-shadow: 
                inset 0 0 15px rgba(255, 105, 180, 0.5),
                0 0 20px rgba(255, 20, 147, 0.4);
        }

        .action-buttons {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
            gap: 10px;
            margin-bottom: 20px;
        }

        .btn-action, .btn-npc {
            background: linear-gradient(to bottom, var(--accent-color), #8D7B68);
            color: white;
            border: none;
            border-radius: 6px;
            padding: 10px 8px;
            cursor: pointer;
            font-family: inherit;
            font-size: clamp(0.95rem, 1.5vw, 1.05rem);
            transition: var(--transition);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            box-shadow: 0 3px 6px rgba(141, 123, 104, 0.2);
        }

        .btn-action:hover, .btn-npc:hover {
            background: linear-gradient(to bottom, var(--button-hover-bg), #7a6856);
            transform: translateY(-2px);
            box-shadow: 0 5px 10px rgba(141, 123, 104, 0.3);
        }

        .npc-buttons {
            border-top: 1px solid var(--border-color-light);
            padding-top: 15px;
        }

        .npc-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
            gap: 10px;
        }

        /* Modal Styles */
        .modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.75);
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            opacity: 0;
            visibility: hidden;
            transition: var(--transition);
            padding: 15px;
        }

        .modal-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .modal-content {
            font-family: var(--font-main);
            background-color: var(--bg-color);
            border: 2px solid var(--border-color-main);
            border-radius: 12px;
            padding: 20px;
            width: 100%;
            max-width: 600px;
            box-shadow: var(--shadow);
            position: relative;
            max-height: 85vh;
            overflow-y: auto;
            transform: translateY(20px);
            transition: all 0.4s ease;
        }

        .modal-overlay.active .modal-content {
            transform: translateY(0);
        }

        .modal-close {
            position: absolute;
            top: 12px;
            right: 18px;
            font-size: 1.8em;
            line-height: 1;
            font-weight: bold;
            cursor: pointer;
            color: var(--text-color);
            transition: color 0.3s ease;
            width: 36px;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
        }

        .modal-close:hover {
            color: #B53331;
            background: rgba(141, 123, 104, 0.1);
        }

        .modal-title {
            font-size: clamp(1.3rem, 2.2vw, 1.6rem);
            text-align: center;
            color: var(--text-color);
            margin-bottom: 15px;
            padding-bottom: 12px;
            border-bottom: 1px solid var(--border-color-light);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
        }

        .modal-body ul {
            list-style: none;
            padding: 0;
            color: var(--text-color);
        }

        .modal-body li {
            padding: 12px 8px;
            border-bottom: 1px solid var(--border-color-light);
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: clamp(0.95rem, 1.5vw, 1.05rem);
            transition: background-color 0.2s;
        }

        .modal-body li:hover {
            background-color: rgba(141, 123, 104, 0.05);
        }

        .modal-body li:last-child {
            border-bottom: none;
        }

        .prop-label {
            font-weight: bold;
            min-width: 100px;
        }

        .sub-item {
            padding-left: 25px !important;
            font-size: clamp(0.9rem, 1.4vw, 1rem) !important;
            background-color: rgba(141, 123, 104, 0.03);
        }

        .status-info {
            background-color: var(--bg-color);
            border: 2px solid var(--border-color-main);
            border-radius: 12px;
            padding: 20px;
            box-shadow: var(--shadow);
            backdrop-filter: blur(3px);
            transition: var(--transition);
            max-height: 85vh;
            overflow-y: auto;
        }

        .info-header {
            display: flex;
            align-items: center;
            gap: 10px;
            margin-bottom: 15px;
            padding-bottom: 12px;
            border-bottom: 1px solid var(--border-color-light);
        }

        .info-header i {
            font-size: 1.6rem;
            color: var(--accent-color);
        }

        .info-content {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
            gap: 15px;
        }

        .info-card {
            background: rgba(245, 239, 230, 0.5);
            border-radius: 8px;
            padding: 15px;
            text-align: center;
            box-shadow: 0 4px 8px rgba(0,0,0,0.05);
            transition: var(--transition);
        }

        .info-card:hover {
            transform: translateY(-3px);
            box-shadow: 0 6px 12px rgba(0,0,0,0.08);
        }

        .info-card h3 {
            font-size: 1.05rem;
            margin-bottom: 10px;
            color: var(--accent-color);
        }

        .info-card p {
            font-size: 1.5rem;
            font-weight: bold;
            color: var(--text-color);
        }

        .info-card small {
            display: block;
            font-size: 0.85rem;
            color: #888;
            margin-top: 4px;
        }

        footer {
            text-align: center;
            margin-top: 20px;
            color: var(--accent-color);
            font-size: 0.85rem;
            padding: 12px;
        }

        /* Animation for progress bar */
        @keyframes progressAnimation {
            0% { background-position: 0 0; }
            100% { background-position: 40px 0; }
        }

        .progress-bar-fill {
            background-image: linear-gradient(45deg, rgba(255, 255, 255, 0.15) 25%, transparent 25%, transparent 50%, rgba(255, 255, 255, 0.15) 50%, rgba(255, 255, 255, 0.15) 75%, transparent 75%, transparent);
            background-size: 40px 40px;
            animation: progressAnimation 1.5s linear infinite;
        }

        /* Responsive adjustments */
        @media (max-width: 768px) {
            .status-container {
                padding: 18px 12px;
            }

            .char-info, .location-info, .identity-info {
                gap: 10px 12px;
            }

            .action-buttons {
                grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
                gap: 8px;
            }

            .npc-grid {
                grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
            }

            .modal-content {
                padding: 18px 12px;
            }

            .info-content {
                grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
                gap: 12px;
            }
        }

        @media (max-width: 480px) {
            .header-info {
                flex-direction: column;
                gap: 5px;
            }

            .char-info, .identity-info {
                flex-direction: column;
                gap: 8px;
            }

            .action-buttons {
                grid-template-columns: 1fr;
            }

            .npc-grid {
                grid-template-columns: 1fr;
            }

            .container {
                gap: 15px;
            }
        }
    </style>
</head>
