    /* 安全地获取值的函数*/
    function SafeGetValue(value, defaultValue = "未知") {
    // 处理 undefined 或 null 的情况
    if (value === undefined || value === null) {
        return defaultValue;
    }

    let result;
    // 处理数组的情况
    if (Array.isArray(value)) {
        result = value.length > 0 ? value[0] : defaultValue;
    } else {
        result = value; // 非数组直接取值
    }

    // 检查结果是否包含 "->"
    if (typeof result === 'string' && result.includes('->')) {
        // 分割字符串并取最后部分
        const parts = result.split('->');
        return parts.length > 1 
            ? parts.slice(1).join('->')  // 保留所有 "->" 后的内容
            : result; // 意外情况返回原字符串
    }

    return result;
    }


    function getDebuffStage(value, type = 'user') {
        const stages = type === 'user' ? 
            {0: '纯白之囚', 200: '红痕之萌', 400: '媚骨初成', 600: '牝堕之宴', 800: '极乐肉器'} : 
            {0: '坚守底线', 200: '摇摆不定', 400: '随波逐流', 600: '沉湎欲海', 800: '彻底沦魔'};

        let stage = 'N/A';
        for (const threshold in stages) { 
            if (value >= threshold) stage = stages[threshold]; 
        }
        return stage;
    }

    function getLustStage(value) {
        const stages = {0: '心如止水', 20: '微澜初起', 40: '心猿意马', 60: '情欲难耐', 80: '欲火焚身'};
        let stage = 'N/A';
        for (const threshold in stages) { 
            if (value >= threshold) stage = stages[threshold]; 
        }
        return stage; 
    }

    function populateModal(bodyId, dataObj) {
        const body = document.getElementById(bodyId);
        if (!body) return;

        let content = '<ul>';
        for (const key in dataObj) {
            if (typeof dataObj[key] === 'object' && dataObj[key] !== null && key === "私处") {
                content += `<li><span class="prop-label">${key}</span><span></span></li>`;
                for(const subKey in dataObj[key]) {
                   content += `<li class="sub-item"><span class="prop-label">${subKey}</span><span>${dataObj[key][subKey]}</span></li>`;
                }
            } else { 
                content += `<li><span class="prop-label">${key}</span><span>${dataObj[key]}</span></li>`; 
            }
        }
        content += '</ul>';
        body.innerHTML = content;
    }

