            padding-bottom: 12px;
            border-bottom: 1px solid var(--border-color-light);
            letter-spacing: 1px;
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 10px 15px;
        }

        .char-info, .location-info, .identity-info {
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
            gap: 15px 20px;
            margin-bottom: 15px;
            font-size: clamp(1rem, 1.8vw, 1.1rem);
