        const stages = type === 'user' ? 
            {0: '纯白之囚', 200: '红痕之萌', 400: '媚骨初成', 600: '牝堕之宴', 800: '极乐肉器'} : 
            {0: '坚守底线', 200: '摇摆不定', 400: '随波逐流', 600: '沉湎欲海', 800: '彻底沦魔'};

        let stage = 'N/A';
        for (const threshold in stages) { 
            if (value >= threshold) stage = stages[threshold]; 
        }
        return stage;
    }

    function getLustStage(value) {
        const stages = {0: '心如止水', 20: '微澜初起', 40: '心猿意马', 60: '情欲难耐', 80: '欲火焚身'};
        let stage = 'N/A';
        for (const threshold in stages) { 
            if (value >= threshold) stage = stages[threshold]; 
        }
        return stage; 
    }

    function populateModal(bodyId, dataObj) {
        const body = document.getElementById(bodyId);
        if (!body) return;

        let content = '<ul>';
        for (const key in dataObj) {
            if (typeof dataObj[key] === 'object' && dataObj[key] !== null && key === "私处") {
                content += `<li><span class="prop-label">${key}</span><span></span></li>`;
                for(const subKey in dataObj[key]) {
                   content += `<li class="sub-item"><span class="prop-label">${subKey}</span><span>${dataObj[key][subKey]}</span></li>`;
                }
            } else { 
                content += `<li><span class="prop-label">${key}</span><span>${dataObj[key]}</span></li>`; 
            }
        }
        content += '</ul>';
        body.innerHTML = content;
    }

    function updateDataSource(gameData) {
        // Update header info
        document.getElementById('header-date').textContent = `${SafeGetValue(gameData.世界.月)}·${SafeGetValue(gameData.世界.日)}`;
        document.getElementById('header-time').textContent = SafeGetValue(gameData.世界.时间);
        document.getElementById('header-weather').textContent = SafeGetValue(gameData.世界.气候);

        // Update footer year
        document.getElementById('year').textContent = SafeGetValue(gameData.世界.年);

        // Update user info
        document.getElementById('user-name').textContent = SafeGetValue(gameData.user.姓名);
        document.getElementById('user-age').textContent = SafeGetValue(gameData.user.年龄);
        document.getElementById('user-gender').textContent = SafeGetValue(gameData.user.性别);
        document.getElementById('user-location').textContent = SafeGetValue(gameData.user.所在位置);
        document.getElementById('user-official-identity').textContent = SafeGetValue(gameData.user.明面身份);
        document.getElementById('user-secret-title').textContent = SafeGetValue(gameData.user.暗中称号);

        // Update status bars
        document.getElementById('user-debuff-bar').style.width = `${Math.min(100, SafeGetValue(gameData.user.堕落值)/10)}%`;
        document.getElementById('user-debuff-stage').textContent = getDebuffStage(SafeGetValue(gameData.user.堕落值), 'user');
        document.getElementById('user-lust-bar').style.width = `${SafeGetValue(gameData.user.情欲值)}%`;
        document.getElementById('user-lust-stage').textContent = getLustStage(SafeGetValue(gameData.user.情欲值));

        // Update status overview
        document.getElementById('health-status').textContent = SafeGetValue(gameData.user.健康状态.状态);
        document.getElementById('health-detail').textContent = SafeGetValue(gameData.user.健康状态.详情);
        document.getElementById('mental-status').textContent = SafeGetValue(gameData.user.精神状态.状态);
        document.getElementById('mental-detail').textContent = SafeGetValue(gameData.user.精神状态.详情);
        document.getElementById('current-goal').textContent = SafeGetValue(gameData.user.当前目标.目标);
        document.getElementById('goal-detail').textContent = SafeGetValue(gameData.user.当前目标.详情);
        document.getElementById('environment-safety').textContent = SafeGetValue(gameData.user.环境安全.状态);
        document.getElementById('safety-detail').textContent = SafeGetValue(gameData.user.环境安全.详情);

        // Populate modals
        populateModal('user-clothing-body', SafeGetValue(gameData.user.服装));
        populateModal('user-body-body', SafeGetValue(gameData.user.身体));
        populateModal('user-items-body', SafeGetValue(gameData.user.物品));

        // Populate NPC grid
        const npcGrid = document.getElementById('npc-grid');
        const npcModal = document.getElementById('npc-modal');
        const npcModalTitle = document.getElementById('npc-modal-title');
        const npcModalBody = document.getElementById('npc-modal-body');
        const npcs = gameData.NPC;

        // 清空现有的NPC按钮
        npcGrid.innerHTML = '';

        for (const npc of npcs) {
            const btn = document.createElement('button');

            btn.className = 'btn-npc';
            btn.innerHTML = `<i class="fas fa-user"></i> ${SafeGetValue(npc.姓名)}`;

            btn.onclick = () => {
                npcModalTitle.innerHTML = `<i class="fas fa-user"></i> ${SafeGetValue(npc.姓名)} - 状态`;

                npcModalBody.innerHTML = `
                    <div class="char-info" style="font-size: 1.1em; margin-bottom: 15px;">
                        <span>${SafeGetValue(npc.姓名)}</span>
                        <span>${SafeGetValue(npc.年龄)}岁</span>
                        <span>${SafeGetValue(npc.性别)}</span>
                    </div>

                    <div class="identity-info" style="font-size: 1.1em; padding: 10px; margin-bottom: 15px;">
                        <span>明面身份：<span>${SafeGetValue(npc.明面身份)}</span></span>
                        <span>暗中称号：<span>${SafeGetValue(npc.暗中称号)}</span></span>
                    </div>

                    <div class="location-info" style="font-size: 1.1em; padding: 10px; margin-bottom: 20px;">
                        <span>所在：${SafeGetValue(npc.所在位置)}</span>
                    </div>

                    <div class="status-bar-container">
                        <div class="status-bar-title">
                            <span>堕落值</span>
                            <span>${getDebuffStage(SafeGetValue(npc.堕落值), 'npc')}</span>
                        </div>
                        <div class="progress-bar">
                            <div class="progress-bar-fill debuff-bar-fill" style="width: ${Math.min(100, SafeGetValue(npc.堕落值)/10)}%;"></div>
                        </div>
                    </div>

                    <div class="status-bar-container">
                        <div class="status-bar-title">
                            <span>情欲值</span>
                            <span>${getLustStage(SafeGetValue(npc.情欲值))}</span>
                        </div>
                        <div class="progress-bar">
                            <div class="progress-bar-fill lust-bar-fill" style="width: ${SafeGetValue(npc.情欲值)}%;"></div>
                        </div>
                    </div>

                    <div id="npc-details-body" style="margin-top: 25px;"></div>
                `;

                const detailsBody = document.getElementById('npc-details-body');
                let detailsHTML = '<ul>';

                // Clothing details
                detailsHTML += '<li><span class="prop-label">服装</span></li>';
                const clothing = npc.服装;
                for(const key in clothing) {
                    detailsHTML += `<li class="sub-item"><span class="prop-label">${key}</span><span>${clothing[key]}</span></li>`;
                }

                // Body status details
                detailsHTML += '<li><span class="prop-label">身体状态</span></li>';
                const body = npc.身体;
                for(const key in body) {
                    if (typeof body[key] === 'object' && body[key] !== null  && key === "私处" ) {
                        detailsHTML += `<li class="sub-item"><span class="prop-label">${key}</span></li>`;
                        for(const subKey in body[key]) { 
                            detailsHTML += `<li class="sub-item" style="padding-left: 40px !important"><span class="prop-label">${subKey}</span><span>${body[key][subKey]}</span></li>`; 
                        }
                    } else { 
                        detailsHTML += `<li class="sub-item"><span class="prop-label">${key}</span><span>${body[key]}</span></li>`; 
                    }
                }

                detailsHTML += '</ul>';
                detailsBody.innerHTML = detailsHTML;

                // Show modal with animation
                npcModal.classList.add('active');
            };

            npcGrid.appendChild(btn);
        }
    }
    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }
            updateDataSource(characterData);
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }        
    }
      // Add event listeners to action buttons
        document.querySelectorAll('.btn-action').forEach(b => {
            b.addEventListener('click', () => { 
                const modalId = b.getAttribute('data-modal') + '-modal';
                const m = document.getElementById(modalId);
                if(m) m.classList.add('active');
            });
        });

        // Close modals when clicking close button or outside
        document.querySelectorAll('.modal-overlay').forEach(m => {
            m.addEventListener('click', e => {
                if (e.target === m || e.target.classList.contains('modal-close')) {
                    m.classList.remove('active');
                }
            });
        });

        // Prevent modal content from closing when clicking inside
        document.querySelectorAll('.modal-content').forEach(content => {
            content.addEventListener('click', e => e.stopPropagation());
        });
    // 初始化显示
    document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
</body>
</html>
